import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`linkedin-inmails`,heroTitle:`Write your InMail sequences in minutes`,heroSubtitle:`Perplexity Computer researches your prospects, writes personalized 3-touch drip sequences, and delivers ready-to-send messages — automatically.`,inputUrlCta:`Write my InMails`,inputUrlPlaceholder:`www.yourcompany.com`,inputUrlPrefill:`Go to {url} and build a LinkedIn InMail outreach campaign. Analyze the company's product, value proposition, and target audience. Then: (1) Research the ideal buyer persona — common pain points, priorities, KPIs they care about, and language they use, (2) Write a 3-touch InMail drip sequence: Message 1 — personalized intro referencing the prospect's role and a specific pain point, Message 2 — follow-up with a case study or proof point, Message 3 — breakup message with a soft ask, (3) Include personalization tokens for each message — {first_name}, {company}, {role}, {recent_news}, {mutual_connection} — with instructions on where to insert them, (4) Write 3 subject line variations per message for A/B testing, (5) Define send timing — days between messages and optimal send windows. Deliver everything as an outreach playbook with message templates, personalization guide, subject line variations, and send schedule.`,heroOverlaySteps:[`Analyzing your website to identify product, audience, and ideal buyer persona`,`Researching target role — pain points, priorities, and language they use`,`Writing a 3-touch InMail drip with personalization tokens and subject lines`,`Outreach playbook with templates, timing, and A/B test plan — ready to send`],generatingSteps:[`Visiting {url} to understand your product, audience, and ideal buyer persona`,`Designing an agent to research target roles and craft personalized messaging`,`Configuring 3-touch drip sequences with personalization tokens and subject lines`,`Setting up outreach playbook with templates, timing, and A/B testing plan`],featureSectionTitle:`From URL to outreach campaign`,featureCardTitles:[`Connects to your outreach tools`,`Messages ready to send`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Pipedrive, Google Sheets, Notion — Computer plugs into your tools so sequences go straight from draft to send.`,`Personalized InMails. Subject line variations. Follow-up cadences. Computer delivers sequences your team can launch immediately.`],capabilitySectionTitle:`Your outreach team, on autopilot`,capabilitySectionSubtitle:`Paste your website, get back a complete InMail campaign.`,capabilityCards:[{title:`Buyer Research`,description:`Computer researches your target role — pain points, priorities, KPIs, and the language they use — so every message resonates.`},{title:`Sequence Writing`,description:`Computer writes a 3-touch InMail drip — personalized intro, proof-point follow-up, and soft-ask breakup — with tokens for each prospect.`},{title:`Subject Line Testing`,description:`Computer writes 3 subject line variations per message for A/B testing — optimized for open rates on LinkedIn.`},{title:`Connect Your Tools`,description:`Computer connects to LinkedIn, HubSpot, Salesforce, and more — so sequences sync with your CRM and outreach tools.`},{title:`Learns Your Voice`,description:`Computer remembers your messaging style, past sequences, and what gets replies across sessions — so every campaign gets sharper.`},{title:`Reply Monitoring`,description:`Computer tracks InMail opens and replies — and alerts you when a prospect engages or a sequence needs adjustment.`}]});export{t as default};
